 "content": "from collections import deque


def transform(grid):
    """Pack monochrome connected objects toward the full-width wall row."""
    h, w = len(grid), len(grid[0])
    wall_row = next(
        (r for r in (0, h - 1) if grid[r] and all(v == grid[r][0] and v != 0 for v in grid[r])),
        None,
    )
    if wall_row is None:
        return [row[:] for row in grid]

    wall_color = grid[wall_row][0]
    wall_cells = {(wall_row, c) for c in range(w)}
    seen = set(wall_cells)
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == wall_color or (r, c) in seen:
                continue
            cells = set()
            queue = deque([(r, c)])
            seen.add((r, c))
            while queue:
                rr, cc = queue.popleft()
                cells.add((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        queue.append((nr, nc))
            objects.append((color, cells))

    toward = 1 if wall_row == 0 else -1
    # Objects nearest the wall settle first; all others fall onto the settled ones.
    objects.sort(key=lambda item: min(r for r, _ in item[1]) if toward == 1
                 else -max(r for r, _ in item[1]))
    occupied = set(wall_cells)
    settled = []
    for color, cells in objects:
        shift = 0
        while True:
            next_cells = {(r + toward * (shift + 1), c) for r, c in cells}
            if any(r < 0 or r >= h or (r, c) in occupied for r, c in next_cells):
                break
            shift += 1
        moved = {(r + toward * shift, c) for r, c in cells}
        settled.append((color, moved))
        occupied.update(moved)

    out = [[0] * w for _ in range(h)]
    for r, c in wall_cells:
        out[r][c] = wall_color
    for color, cells in settled:
        for r, c in cells:
            out[r][c] = color
    return out
